'use strict';

// MODULES //

var absf = require( '@stdlib/math/base/special/absf' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var FLOAT_EPS = require( '@stdlib/constants/float32/eps' );
var sumSeries = require( '@stdlib/math/base/tools/sum-series' );
var f32 = require( '@stdlib/number/float64/base/to-float32' );
var log1pfSeries = require( './log1pf_series.js' );


// VARIABLES //

var ONE = f32( 1.0 );
var TWO = f32( 2.0 );


// MAIN //

/**
* Evaluates \\( \operatorname{log1pmxf}(x) = \lnf(1+x) - x \\) for a single-precision floating point number.
*
* @param {number} x - input value
* @returns {number} function value
*
* @example
* var v = log1pmxf( 1.1 );
* // returns ~-0.358
*
* @example
* var v = log1pmxf( -1.1 );
* // returns NaN
*/
function log1pmxf( x ) {
	var opts;
	var ax;
	x = f32( x );

	if ( x <= -ONE ) {
		return NaN;
	}

	ax = absf( x );

	// Large |x|: safe direct computation
	if ( ax > f32( 0.95 ) ) {
		return f32( lnf( f32( ONE + x ) ) - x );
	}

	// Very small x: use first Taylor term
	if ( ax < FLOAT_EPS ) {
		return f32( -x * x / TWO );
	}

	opts = {
		'initialValue': f32( -x )
	};

	return f32( sumSeries( log1pfSeries( x ), opts ) );
}


// EXPORTS //

module.exports = log1pmxf;
